import { readFileSync } from 'node:fs'
import { test } from '@e2e-dev/web'
import { expect } from 'e2e'

// Only synthetic, authorized local Worker snapshots generated by the owning
// native-run-trace integration. No production/private source is read here.
test.describe('Trace execution data', { ...(process.env.ISSUE296_SNAPSHOTS ? {} : { skip: 'Requires owning local trace snapshots.' }) }, () => {
  test('first load, replay and reload preserve real run/model/tool endpoints',async ({ app,browser,screen }) => {
    const snapshots = JSON.parse(readFileSync(process.env.ISSUE296_SNAPSHOTS!,'utf8'))
    const send = (name: string) => browser.evaluate(snapshot=>{
      window.dispatchEvent(new CustomEvent('native-streaming-snapshot',{ detail: snapshot }));return true
    },snapshots[name])
    for (const name of ['running','initial','replay','reload']) {
      const expected = snapshots[name].message.metadata.custom.runTrace
      const spans = [expected.root,...expected.root.children]
      await app.open('/e2e/native-streaming.html')
      await send(name)
      await browser.locator('[data-slot="run-activity"] button').first().tap()
      await expect(screen.getByRole('region','运行瀑布图')).toBeVisible()
      const actual = await browser.evaluate(()=>[...document.querySelectorAll<HTMLElement>('[data-trace-lane]')].map(node=>({
        start: node.dataset.traceStart === '' ? null : Number(node.dataset.traceStart),end: node.dataset.traceEnd === '' ? null : Number(node.dataset.traceEnd),
      })))
      expect(actual).toEqual(spans.map((span: { start: number|null;end: number|null })=>({ start: span.start,end: span.end })))
      await screen.getByRole('button','查看 运行 详情').tap()
      expect(await browser.locator('[data-trace-time="start"]').getAttribute('datetime')).toBe(new Date(expected.startedAt+expected.root.start).toISOString())
      if (expected.root.end === null) await expect(browser.locator('[data-trace-time="end"]')).toHaveCount(0)
      else expect(await browser.locator('[data-trace-time="end"]').getAttribute('datetime')).toBe(new Date(expected.startedAt+expected.root.end).toISOString())
      await expect(browser.locator('[data-trace-axis]')).toBeVisible()
      expect(await browser.evaluate(()=>document.querySelector('[data-slot="trace-waterfall"]')?.textContent ?? '')).not.toMatch(/起点未知|时间未知|耗时未知/)
      await app.screenshot(`trace-real-times-${name}`)
    }
  })
  test('historical duration-only embedding and partial cost keep useful data without invented offsets',async ({ app,browser,screen }) => {
    const snapshots = JSON.parse(readFileSync(process.env.ISSUE296_SNAPSHOTS!,'utf8'))
    const value = snapshots.initial
    const root = value.message.metadata.custom.runTrace.root
    const call = (id: string,kind: string,durationMs: number,cost: number|null)=>({ id,name: kind === 'embedding' ? '向量编码' : '模型调用',kind,
      status: 'complete',start: null,end: null,durationMs,model: kind === 'embedding' ? 'BAAI/bge-m3' : 'historical-chat',
      tokensIn: 10,tokensOut: 0,cost,costEstimated: cost !== null,children: [] })
    value.message.metadata.custom.runTrace = { version: 1,startedAt: 1000,timingBasis: 'creation',truncated: false,
      limitations: ['llm-offsets','terminal-time','child-discovery'],root: { ...root,start: 0,end: null,durationMs: null,
        cost: null,knownCost: 0.00850644,costIncomplete: true,costEstimated: true,children: [
          call('embedding','embedding',134,null),call('chat-a','llm',33730,0.00506501),call('chat-b','llm',3049,0.00344143),
        ] } }
    await app.open('/e2e/native-streaming.html')
    await browser.evaluate(snapshot=>{ window.dispatchEvent(new CustomEvent('native-streaming-snapshot',{detail: snapshot}));return true },value)
    await browser.locator('[data-slot="run-activity"] button').first().tap()
    await expect(browser.locator('[data-trace-axis]')).toHaveCount(0)
    await expect(browser.locator('[data-trace-bar]')).toHaveCount(0)
    await expect(screen.getByText('134 ms',{exact: true})).toBeVisible()
    await expect(screen.getByText('33,730 ms',{exact: true})).toBeVisible()
    expect(await browser.evaluate(()=>document.querySelector('[data-slot="trace-waterfall"]')?.textContent ?? '')).toContain('已计约 $0.00850644')
    await screen.getByRole('button','查看 运行 详情').tap()
    await expect(browser.locator('[data-trace-time="start"]')).toHaveCount(0)
    await screen.getByRole('button','查看 向量编码 详情').tap()
    await expect(screen.getByText('BAAI/bge-m3',{exact: true})).toBeVisible()
    await app.screenshot('trace-historical-duration-and-partial-cost')
  })
})
